from collections import deque
import heapq


def match(orders):
    buy_heap = []   # max-heap via negated prices
    sell_heap = []  # min-heap
    buy_levels = {}   # price -> deque of order dicts
    sell_levels = {}  # price -> deque of order dicts
    order_map = {}    # id -> order dict (only for resting orders)

    trades = []

    def add_resting(side, oid, price, qty):
        od = {'id': oid, 'price': price, 'qty': qty, 'active': True, 'side': side}
        order_map[oid] = od
        if side == 'buy':
            if price not in buy_levels:
                buy_levels[price] = deque()
                heapq.heappush(buy_heap, -price)
            buy_levels[price].append(od)
        else:
            if price not in sell_levels:
                sell_levels[price] = deque()
                heapq.heappush(sell_heap, price)
            sell_levels[price].append(od)

    def best_sell_price():
        while sell_heap:
            p = sell_heap[0]
            level = sell_levels.get(p)
            if level is None:
                heapq.heappop(sell_heap)
                continue
            while level and (not level[0]['active'] or level[0]['qty'] <= 0):
                level.popleft()
            if not level:
                del sell_levels[p]
                heapq.heappop(sell_heap)
                continue
            return p
        return None

    def best_buy_price():
        while buy_heap:
            negp = buy_heap[0]
            p = -negp
            level = buy_levels.get(p)
            if level is None:
                heapq.heappop(buy_heap)
                continue
            while level and (not level[0]['active'] or level[0]['qty'] <= 0):
                level.popleft()
            if not level:
                del buy_levels[p]
                heapq.heappop(buy_heap)
                continue
            return p
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            od = order_map.get(oid)
            if od is not None and od['active'] and od['qty'] > 0:
                od['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                sp = best_sell_price()
                if sp is None:
                    break
                if typ in ('limit', 'ioc') and price < sp:
                    break
                level = sell_levels[sp]
                while remaining > 0 and level:
                    front = level[0]
                    if not front['active'] or front['qty'] <= 0:
                        level.popleft()
                        continue
                    trade_qty = min(remaining, front['qty'])
                    trades.append([oid, front['id'], sp, trade_qty])
                    front['qty'] -= trade_qty
                    remaining -= trade_qty
                    if front['qty'] <= 0:
                        front['active'] = False
                        level.popleft()
                if not level:
                    del sell_levels[sp]

            if remaining > 0 and typ == 'limit':
                add_resting('buy', oid, price, remaining)

        else:  # side == 'sell'
            while remaining > 0:
                bp = best_buy_price()
                if bp is None:
                    break
                if typ in ('limit', 'ioc') and price > bp:
                    break
                level = buy_levels[bp]
                while remaining > 0 and level:
                    front = level[0]
                    if not front['active'] or front['qty'] <= 0:
                        level.popleft()
                        continue
                    trade_qty = min(remaining, front['qty'])
                    trades.append([front['id'], oid, bp, trade_qty])
                    front['qty'] -= trade_qty
                    remaining -= trade_qty
                    if front['qty'] <= 0:
                        front['active'] = False
                        level.popleft()
                if not level:
                    del buy_levels[bp]

            if remaining > 0 and typ == 'limit':
                add_resting('sell', oid, price, remaining)

